import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25.5, C: 0.1, D: 100, E: 33.33 }
const pricing = { priceOf: async (sku) => prices[sku] }

async function withServer(fn) {
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  const base = `http://localhost:${server.address().port}`
  try { return await fn(base) } finally { server.close() }
}

const post = (base, items) =>
  fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) }).then((r) => r.json())

// Characterization tests: pin CURRENT behaviour of order totals (euros).
const cases = [
  ['single item, no discount', [{ sku: 'A', qty: 1 }], 10],
  ['multiple items, no discount', [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }], 71],
  ['exactly 100 gets no discount', [{ sku: 'D', qty: 1 }], 100],
  ['just over 100 gets 10% off (100.5 -> 90.45 -> 90)', [{ sku: 'D', qty: 1 }, { sku: 'C', qty: 5 }], 90],
  ['larger order: 10 x 25.5 = 255 -> 229.5 -> 229', [{ sku: 'B', qty: 10 }], 229],
  ['large order: 50 x 10 = 500 -> 450', [{ sku: 'A', qty: 50 }], 450],
  // Cents are dropped by Math.floor, so fractional totals lose value.
  ['fractional total below threshold is floored (3 x 33.33 = 99.99 -> 99)', [{ sku: 'E', qty: 3 }], 99],
  ['fractional discounted total is floored (4 x 33.33 = 133.32 -> 119.988 -> 119)', [{ sku: 'E', qty: 4 }], 119],
  // Single flat tier: no bigger discount for bigger orders.
  ['no extra tier: 1000 -> 900', [{ sku: 'D', qty: 10 }], 900],
]

for (const [name, items, total] of cases) {
  test(name, () => withServer(async (base) => {
    const order = await post(base, items)
    assert.equal(order.total, total)
  }))
}

test('stored order returns the same total', () => withServer(async (base) => {
  const created = await post(base, [{ sku: 'A', qty: 50 }])
  const fetched = await fetch(`${base}/orders/${created.id}`).then((r) => r.json())
  assert.equal(fetched.total, 450)
}))
EOF
